use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Exp {
    Const(i32),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

impl Exp {
    /// Evaluate the expression under the given store.
    /// Variables not found in the store default to -1.
    pub fn eval(&self, store: &HashMap<String, i32>) -> i32 {
        match self {
            Exp::Const(c) => *c,
            Exp::Var(name) => *store.get(name).unwrap_or(&-1),
            Exp::Plus(l, r) => l.eval(store) + r.eval(store),
            Exp::Mult(l, r) => l.eval(store) * r.eval(store),
        }
    }

    /// Perform a one‐step, root‐only peephole optimization.
    pub fn optimize(self) -> Exp {
        match self {
            Exp::Mult(l, r) => {
                // Take ownership of the inner Exps by moving out of the Boxes
                match (*l, *r) {
                    // constant folding
                    (Exp::Const(a), Exp::Const(b)) => Exp::Const(a * b),
                    // absorbing element 0
                    (Exp::Const(0), _) => Exp::Const(0),
                    (_, Exp::Const(0)) => Exp::Const(0),
                    // neutral element 1
                    (Exp::Const(1), right) => right,
                    (left, Exp::Const(1)) => left,
                    // no rule applies: rebuild the node unchanged
                    (left, right) => Exp::Mult(Box::new(left), Box::new(right)),
                }
            }
            Exp::Plus(l, r) => {
                match (*l, *r) {
                    // constant folding
                    (Exp::Const(a), Exp::Const(b)) => Exp::Const(a + b),
                    // neutral element 0
                    (Exp::Const(0), right) => right,
                    (left, Exp::Const(0)) => left,
                    // no rule applies: rebuild the node unchanged
                    (left, right) => Exp::Plus(Box::new(left), Box::new(right)),
                }
            }
            // For Const and Var, nothing to do
            other => other,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_eval_and_optimize() {
        let mut store = HashMap::new();
        store.insert("x".to_string(), 5);
        store.insert("y".to_string(), 10);

        // ((x * 1) + (0 * y))  => optimize at root: it's a Plus node
        let expr = Exp::Plus(
            Box::new(Exp::Mult(
                Box::new(Exp::Var("x".into())),
                Box::new(Exp::Const(1)),
            )),
            Box::new(Exp::Mult(
                Box::new(Exp::Const(0)),
                Box::new(Exp::Var("y".into())),
            )),
        );

        let original = expr.clone();
        let v0 = original.eval(&store);

        // optimize only at the topmost Plus:
        // Left side (x*1) and right side (0*y) are not themselves optimized
        // because we do not recurse.
        // But on the root Plus, we see both sides are not constants nor zero,
        // so the Plus remains unchanged.
        let opt1 = expr.optimize();
        assert_eq!(opt1, original);
        assert_eq!(opt1.eval(&store), v0);

        // Now explicitly optimize the two Mult subexpressions:
        let mult1 = Exp::Mult(
            Box::new(Exp::Var("x".into())),
            Box::new(Exp::Const(1)),
        );
        let mult2 = Exp::Mult(
            Box::new(Exp::Const(0)),
            Box::new(Exp::Var("y".into())),
        );
        assert_eq!(mult1.optimize(), Exp::Var("x".into()));
        assert_eq!(mult2.optimize(), Exp::Const(0));

        // As a full expression if we had recursively optimized:
        let full_opt = Exp::Plus(
            Box::new(mult1.optimize()),
            Box::new(mult2.optimize()),
        )
        .optimize();
        // Now the root Plus sees (x + 0) and reduces to x
        assert_eq!(full_opt, Exp::Var("x".into()));
        assert_eq!(full_opt.eval(&store), 5);
    }
}